=== FILE: rr_arbiter.v ===
// rr_arbiter: round-robin arbiter for N requesters.
//
// Implements interface_spec.md / microarchitecture.md:
// - one priority pointer `ptr` ($clog2(N) bits), reset to 0 (sync, active low)
// - grant is combinational from req and ptr: the first requester with req
//   high at or after ptr, searching upwards and wrapping from N-1 to 0
// - on a rising edge with a grant (out of reset) ptr becomes winner + 1,
//   wrapping at N (not at a power of two); with no request ptr holds
module rr_arbiter #(
    parameter integer N = 4
) (
    input  wire         clk,
    input  wire         rst_n,
    input  wire [N-1:0] req,
    output reg  [N-1:0] grant
);

    localparam integer PW = $clog2(N);

    reg  [PW-1:0] ptr;
    reg  [PW-1:0] ptr_next;
    reg           found;
    integer       ptr_i;
    integer       idx;
    integer       win_i;
    integer       nxt;
    integer       k;

    // Grant logic and next pointer: every variable has a default first.
    always @* begin
        grant    = {N{1'b0}};
        found    = 1'b0;
        ptr_i    = {{(32-PW){1'b0}}, ptr};
        idx      = 0;
        win_i    = 0;
        nxt      = 0;
        ptr_next = ptr;
        for (k = 0; k < N; k = k + 1) begin
            idx = ptr_i + k;
            if (idx >= N) begin
                idx = idx - N;
            end
            if (!found && req[idx[PW-1:0]]) begin
                grant[idx[PW-1:0]] = 1'b1;
                found              = 1'b1;
                win_i              = idx;
            end
        end
        if (found) begin
            nxt = win_i + 1;
            if (nxt >= N) begin
                nxt = 0;
            end
            ptr_next = nxt[PW-1:0];
        end
    end

    // Pointer register: reset value and update only.
    always @(posedge clk) begin
        if (!rst_n) begin
            ptr <= {PW{1'b0}};
        end else begin
            ptr <= ptr_next;
        end
    end

`ifdef FORMAL
    // Design-intent properties (not yet proven; see task notes).
    reg f_past_valid;
    initial f_past_valid = 1'b0;
    always @(posedge clk) begin
        f_past_valid <= 1'b1;
    end

    always @(*) begin
        if (!f_past_valid) begin
            assume (!rst_n);
        end
    end

    integer f_ptr;
    integer f_dw;
    integer f_k;

    always @(*) begin
        f_ptr = {{(32-PW){1'b0}}, ptr};
        f_dw  = (win_i - f_ptr + N) % N;
        if (f_past_valid) begin
            assert (f_ptr < N);
            assert ((grant & ~req) == {N{1'b0}});
            assert ((grant & (grant - {{(N-1){1'b0}}, 1'b1})) == {N{1'b0}});
            assert ((req == {N{1'b0}}) || (grant != {N{1'b0}}));
            assert (found == (grant != {N{1'b0}}));
            if (found) begin
                assert (req[win_i[PW-1:0]]);
                assert (grant[win_i[PW-1:0]]);
                for (f_k = 0; f_k < N; f_k = f_k + 1) begin
                    if (f_k < f_dw) begin
                        assert (!req[(f_ptr + f_k) % N]);
                    end
                end
            end
        end
    end

    always @(posedge clk) begin
        if (f_past_valid) begin
            if (!$past(rst_n)) begin
                assert (ptr == {PW{1'b0}});
            end else if ($past(found)) begin
                assert (f_ptr == (($past(win_i) + 1) % N));
            end else begin
                assert (ptr == $past(ptr));
            end
            cover ($past(rst_n) && $past(found) && ($past(win_i) == N - 1));
        end
    end

    always @(*) begin
        if (f_past_valid && rst_n) begin
            cover (&req);
        end
    end

    genvar gi;
    generate
        for (gi = 0; gi < N; gi = gi + 1) begin : g_fair
            integer f_wait;
            integer f_dist;
            initial f_wait = 0;
            always @(posedge clk) begin
                if (!rst_n || !req[gi] || grant[gi]) begin
                    f_wait <= 0;
                end else begin
                    f_wait <= f_wait + 1;
                end
            end
            always @(*) begin
                f_dist = (gi - f_ptr + N) % N;
                if (f_past_valid) begin
                    assert (f_wait >= 0);
                    assert (f_wait <= N - 1);
                    assert (f_wait + f_dist <= N - 1);
                    if (rst_n) begin
                        cover (grant[gi]);
                    end
                end
            end
        end
    endgenerate
`endif

endmodule
=== END FILE ===
