// rr_arbiter_tb: self-checking testbench for rr_arbiter at N=4 and N=5.
//
// Stimulus changes on the falling edge; each checker samples on the rising
// edge (before the pointer updates), compares grant with a reference pointer
// model, checks the grant properties and the N-1 fairness bound, and records
// coverage of every case the interface spec lists.

module rr_arbiter_chk #(
    parameter integer N = 4
) (
    input  wire         clk,
    input  wire         rst_n,
    input  wire [N-1:0] req,
    input  wire [N-1:0] grant,
    input  wire         done,
    output reg  [31:0]  passed,
    output reg  [31:0]  failed
);
    reg         started = 1'b0;
    reg         reported;
    integer     m_ptr;
    integer     w;
    integer     k;
    integer     i;
    integer     idx;
    integer     maxwait;
    integer     waitc [0:N-1];
    reg [N-1:0] exp_grant;
    reg [N-1:0] oh;
    reg [N-1:0] prev_req;
    reg [N-1:0] prev_grant;
    reg         prev_valid;
    reg         prev_rstn;
    reg         had_traffic;
    reg         cov_none;
    reg         cov_all;
    reg         cov_held;
    reg         cov_rst_traffic;
    reg         cov_wrap;
    reg [N-1:0] cov_alone;

    task cov_check;
        input         hit;
        input integer id;
        begin
            if (hit) begin
                passed = passed + 32'd1;
            end else begin
                failed = failed + 32'd1;
                case (id)
                    0: $error("rr_arbiter N=%0d: coverage missed: a cycle with no requests", N);
                    1: $error("rr_arbiter N=%0d: coverage missed: everyone requesting", N);
                    2: $error("rr_arbiter N=%0d: coverage missed: a held request among changing others", N);
                    3: $error("rr_arbiter N=%0d: coverage missed: reset during traffic", N);
                    4: $error("rr_arbiter N=%0d: coverage missed: pointer wrap from N-1 to 0", N);
                    5: $error("rr_arbiter N=%0d: coverage missed: longest fair wait of N-1 cycles", N);
                    default: $error("rr_arbiter N=%0d: coverage missed: requester %0d granted alone", N, id - 16);
                endcase
            end
        end
    endtask

    always @(posedge clk) begin
        if (!started) begin
            if (!rst_n) begin
                started         = 1'b1;
                reported        = 1'b0;
                passed          = 32'd0;
                failed          = 32'd0;
                m_ptr           = 0;
                maxwait         = 0;
                for (i = 0; i < N; i = i + 1) begin
                    waitc[i] = 0;
                end
                prev_req        = {N{1'b0}};
                prev_grant      = {N{1'b0}};
                prev_valid      = 1'b0;
                prev_rstn       = 1'b0;
                had_traffic     = 1'b0;
                cov_none        = 1'b0;
                cov_all         = 1'b0;
                cov_held        = 1'b0;
                cov_rst_traffic = 1'b0;
                cov_wrap        = 1'b0;
                cov_alone       = {N{1'b0}};
            end
        end else if (done) begin
            if (!reported) begin
                reported = 1'b1;
                cov_check(cov_none, 0);
                cov_check(cov_all, 1);
                cov_check(cov_held, 2);
                cov_check(cov_rst_traffic, 3);
                cov_check(cov_wrap, 4);
                cov_check(maxwait == N - 1, 5);
                for (i = 0; i < N; i = i + 1) begin
                    cov_check(cov_alone[i], 16 + i);
                end
            end
        end else begin
            // Reference model: first requester at or after the pointer.
            w = -1;
            for (k = N - 1; k >= 0; k = k - 1) begin
                idx = (m_ptr + k) % N;
                if (req[idx]) begin
                    w = idx;
                end
            end
            exp_grant = {N{1'b0}};
            if (w >= 0) begin
                exp_grant[w] = 1'b1;
            end

            if (grant === exp_grant) begin
                passed = passed + 32'd1;
            end else begin
                failed = failed + 32'd1;
                $error("rr_arbiter N=%0d t=%0t: req %b pointer %0d: grant %b, expected %b",
                       N, $time, req, m_ptr, grant, exp_grant);
            end

            if ((grant & ~req) == {N{1'b0}}) begin
                passed = passed + 32'd1;
            end else begin
                failed = failed + 32'd1;
                $error("rr_arbiter N=%0d t=%0t: grant %b to a requester not asking (req %b)",
                       N, $time, grant, req);
            end

            if ((grant & (grant - {{(N-1){1'b0}}, 1'b1})) == {N{1'b0}}) begin
                passed = passed + 32'd1;
            end else begin
                failed = failed + 32'd1;
                $error("rr_arbiter N=%0d t=%0t: grant %b is not one-hot or zero", N, $time, grant);
            end

            if ((req == {N{1'b0}}) || (grant != {N{1'b0}})) begin
                passed = passed + 32'd1;
            end else begin
                failed = failed + 32'd1;
                $error("rr_arbiter N=%0d t=%0t: req %b but no grant", N, $time, req);
            end

            // Fairness: cycles waited with the request held, out of reset.
            for (i = 0; i < N; i = i + 1) begin
                if (!rst_n || !req[i] || grant[i]) begin
                    waitc[i] = 0;
                end else begin
                    waitc[i] = waitc[i] + 1;
                    if (waitc[i] > maxwait) begin
                        maxwait = waitc[i];
                    end
                    if (waitc[i] <= N - 1) begin
                        passed = passed + 32'd1;
                    end else begin
                        failed = failed + 32'd1;
                        $error("rr_arbiter N=%0d t=%0t: requester %0d has waited %0d cycles (bound %0d)",
                               N, $time, i, waitc[i], N - 1);
                    end
                end
            end

            // Coverage.
            if (rst_n && (req == {N{1'b0}})) begin
                cov_none = 1'b1;
            end
            if (rst_n && (&req)) begin
                cov_all = 1'b1;
            end
            for (i = 0; i < N; i = i + 1) begin
                oh    = {N{1'b0}};
                oh[i] = 1'b1;
                if (rst_n && (req == oh) && grant[i]) begin
                    cov_alone[i] = 1'b1;
                end
                if (rst_n && prev_valid && prev_rstn && prev_req[i] && req[i] && !prev_grant[i] &&
                    ((req & ~oh) != (prev_req & ~oh))) begin
                    cov_held = 1'b1;
                end
            end
            if (!rst_n && had_traffic && (req != {N{1'b0}})) begin
                cov_rst_traffic = 1'b1;
            end
            if (rst_n && (grant != {N{1'b0}})) begin
                had_traffic = 1'b1;
            end

            // Model pointer update at this edge.
            if (!rst_n) begin
                m_ptr = 0;
            end else if (w >= 0) begin
                if (w == N - 1) begin
                    m_ptr    = 0;
                    cov_wrap = 1'b1;
                end else begin
                    m_ptr = w + 1;
                end
            end
            prev_req   = req;
            prev_grant = grant;
            prev_rstn  = rst_n;
            prev_valid = 1'b1;
        end
    end
endmodule

module rr_arbiter_tb;
    reg             clk;
    reg             rst_n;
    reg  [3:0]      req4;
    reg  [4:0]      req5;
    wire [3:0]      grant4;
    wire [4:0]      grant5;
    reg             done;
    wire [31:0]     pass4;
    wire [31:0]     fail4;
    wire [31:0]     pass5;
    wire [31:0]     fail5;
    integer         passed;
    integer         failed;
    integer         j;
    reg  [31:0]     lfsr;
    reg  [31:0]     lfsr2;
    reg  [4:0]      oh;
    reg  [8*64-1:0] nonce;

    rr_arbiter #(.N(4)) u_dut4 (
        .clk  (clk),
        .rst_n(rst_n),
        .req  (req4),
        .grant(grant4)
    );

    rr_arbiter #(.N(5)) u_dut5 (
        .clk  (clk),
        .rst_n(rst_n),
        .req  (req5),
        .grant(grant5)
    );

    rr_arbiter_chk #(.N(4)) u_chk4 (
        .clk   (clk),
        .rst_n (rst_n),
        .req   (req4),
        .grant (grant4),
        .done  (done),
        .passed(pass4),
        .failed(fail4)
    );

    rr_arbiter_chk #(.N(5)) u_chk5 (
        .clk   (clk),
        .rst_n (rst_n),
        .req   (req5),
        .grant (grant5),
        .done  (done),
        .passed(pass5),
        .failed(fail5)
    );

    initial clk = 1'b0;
    always #5 clk = ~clk;

    task next_rand;
        begin
            lfsr = lfsr ^ (lfsr << 13);
            lfsr = lfsr ^ (lfsr >> 17);
            lfsr = lfsr ^ (lfsr << 5);
        end
    endtask

    task drive;
        input       rst_v;
        input [4:0] r4;
        input [4:0] r5;
        begin
            @(negedge clk);
            rst_n = rst_v;
            req4  = r4[3:0];
            req5  = r5;
        end
    endtask

    initial begin
        nonce  = {64{8'h00}};
        passed = 0;
        failed = 0;
        rst_n  = 1'b0;
        req4   = 4'd0;
        req5   = 5'd0;
        done   = 1'b0;
        lfsr   = 32'h1bad_5eed;
        lfsr2  = 32'd0;
        oh     = 5'd0;

        // 1. Reset with no traffic.
        repeat (3) drive(1'b0, 5'd0, 5'd0);
        // 2. No requests: no grant, pointer holds.
        repeat (3) drive(1'b1, 5'd0, 5'd0);
        // 3. Each requester alone.
        for (j = 0; j < 5; j = j + 1) begin
            oh    = 5'd0;
            oh[j] = 1'b1;
            repeat (2) drive(1'b1, oh, oh);
        end
        // 4. Reset during traffic, then everyone requesting: strict rotation
        //    from 0 and the longest fair wait (N-1 cycles).
        drive(1'b0, 5'h1f, 5'h1f);
        repeat (20) drive(1'b1, 5'h1f, 5'h1f);
        // 5. A held request among changing others.
        for (j = 0; j < 30; j = j + 1) begin
            next_rand;
            drive(1'b1, lfsr[4:0] | 5'b00100, lfsr[12:8] | 5'b00100);
        end
        for (j = 0; j < 30; j = j + 1) begin
            next_rand;
            drive(1'b1, lfsr[4:0] | 5'b01000, lfsr[12:8] | 5'b10000);
        end
        // 6. Sparse random requests, dropped and raised.
        for (j = 0; j < 150; j = j + 1) begin
            next_rand;
            lfsr2 = lfsr;
            next_rand;
            drive(1'b1, lfsr[4:0] & lfsr2[4:0], lfsr[12:8] & lfsr2[12:8]);
        end
        // 7. Dense random requests with occasional reset during traffic.
        for (j = 0; j < 400; j = j + 1) begin
            next_rand;
            drive(lfsr[20:16] != 5'd0, lfsr[4:0], lfsr[12:8]);
        end
        // 8. Quiet, then collect coverage and the verdict.
        repeat (2) drive(1'b1, 5'd0, 5'd0);
        @(negedge clk);
        done = 1'b1;
        @(negedge clk);
        @(negedge clk);

        passed = pass4 + pass5;
        failed = fail4 + fail5;
        if ((pass4 == 32'd0) || (pass5 == 32'd0)) begin
            failed = failed + 1;
            $error("rr_arbiter_tb: a checker recorded no passing check");
        end

        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) begin
            nonce = {64{8'h00}};
        end
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end
endmodule
=== END FILE ===
